import type { NodeOptions } from "@sentry/node";
import * as Sentry from "@sentry/node";

type AnyIntegration = { name: string };

export { Sentry };

export type Surface = "daemon" | "extension" | "cli" | "api" | "mcp-proxy";
export type Tier = "free" | "pro" | "team" | "pioneer";

export interface SentryPrivacyOptions {
	dsn: string;
	surface: Surface;
	workspaceHash?: string;
	tier?: Tier;
	release?: string;
	environment?: string;
}

const EXTRA_ALLOWLIST = new Set([
	"requestId",
	"workspaceHash",
	"sessionId",
	"tier",
	"cliVersion",
	"daemonVersion",
	"extensionVersion",
	"platform",
	"nodeVersion",
]);

const BLOCKED_BREADCRUMB_CATEGORIES = new Set(["fetch", "xhr", "console"]);

// Matches /Users/<name>/ and /home/<name>/
const HOME_PATH_RE = /\/(Users|home)\/[^/]+\//g;
// GitHub personal/oauth/user/server tokens
const GH_TOKEN_RE = /(ghp|gho|ghu|ghs)_[A-Za-z0-9]{36}/g;
// OpenAI-style secret keys
const API_KEY_RE = /sk-[A-Za-z0-9]{32,}/g;

const MAX_STRING_LEN = 2048;

function scrubString(value: string): string {
	if (value.length > MAX_STRING_LEN) {
		return `[TRUNCATED:${value.length}]`;
	}
	return value
		.replace(HOME_PATH_RE, "/~/")
		.replace(GH_TOKEN_RE, "[REDACTED_GH_TOKEN]")
		.replace(API_KEY_RE, "[REDACTED_API_KEY]");
}

function scrubValue(value: unknown): unknown {
	if (typeof value === "string") {
		return scrubString(value);
	}
	if (Array.isArray(value)) {
		return value.map(scrubValue);
	}
	if (value !== null && typeof value === "object") {
		return scrubRecord(value as Record<string, unknown>);
	}
	return value;
}

function scrubRecord(obj: Record<string, unknown>): Record<string, unknown> {
	const result: Record<string, unknown> = {};
	for (const [k, v] of Object.entries(obj)) {
		result[k] = scrubValue(v);
	}
	return result;
}

export interface NextjsSentryOptions {
	dsn: string;
	release?: string;
	environment?: string;
	tracesSampleRate?: number;
	ignoreErrors?: (string | RegExp)[];
}

export function createNextjsSentryConfig(options: NextjsSentryOptions): Record<string, unknown> {
	const { dsn, release, environment, tracesSampleRate, ignoreErrors } = options;
	const resolvedEnv = resolveDeploymentEnv(environment);
	return {
		dsn,
		environment: resolvedEnv,
		release:
			release ??
			process.env.VERCEL_GIT_COMMIT_SHA ??
			process.env.NEXT_PUBLIC_VERCEL_GIT_COMMIT_SHA ??
			process.env.npm_package_version,
		sendDefaultPii: false,
		tracesSampleRate: tracesSampleRate ?? (resolvedEnv === "development" ? 1.0 : 0.1),
		ignoreErrors: ignoreErrors ?? ["NetworkError", "Failed to fetch", "Load failed", "AbortError"],
		beforeSend(event: Record<string, unknown>) {
			const req = event.request as Record<string, unknown> | undefined;
			if (req?.headers) {
				const headers = req.headers as Record<string, unknown>;
				delete headers.authorization;
				delete headers.cookie;
				delete headers["x-api-key"];
			}
			const user = event.user as Record<string, unknown> | undefined;
			if (user?.email) {
				user.email = "[REDACTED]";
			}
			const exception = event.exception as Record<string, unknown> | undefined;
			if (exception?.values) {
				for (const exc of exception.values as Array<Record<string, unknown>>) {
					if (exc.value && typeof exc.value === "string") {
						exc.value = scrubString(exc.value);
					}
					const st = exc.stacktrace as Record<string, unknown> | undefined;
					if (st?.frames) {
						for (const frame of st.frames as Array<Record<string, unknown>>) {
							if (typeof frame.filename === "string") {
								frame.filename = scrubString(frame.filename);
							}
							if (typeof frame.abs_path === "string") {
								frame.abs_path = scrubString(frame.abs_path);
							}
						}
					}
				}
			}
			return event;
		},
	};
}

/**
 * Resolve the deployment environment from explicit override, Doppler-aware
 * detection, or platform signals.
 *
 * NODE_ENV is unreliable: Doppler sets it to "production" even for local dev
 * configs. DEPLOYMENT_ENV is the authoritative discriminator  -  it is set
 * explicitly per Doppler config (dev → "development", stg → "staging",
 * prd → "production"). Falls back to platform signals and then NODE_ENV.
 */
function resolveDeploymentEnv(override?: string): string {
	if (override) return override;
	const explicit = process.env.DEPLOYMENT_ENV;
	if (explicit === "development" || explicit === "staging" || explicit === "production") {
		return explicit;
	}
	// Staging Fly.io deploy: FLY_ALLOC_ID is set but DEPLOYMENT_ENV=staging
	// must be present in doppler stg config to reach this branch correctly.
	// Vercel preview deployments are staging, not production.
	if (process.env.VERCEL_ENV === "preview") return "staging";
	// NODE_ENV fallback  -  only reliable when Doppler is not in the picture
	// (e.g. unit tests, or non-Doppler local dev with a hand-crafted .env).
	return process.env.NODE_ENV ?? "production";
}

export function createSentryConfig(options: SentryPrivacyOptions): NodeOptions {
	const { dsn, surface, workspaceHash, tier, release, environment } = options;

	const resolvedEnv = resolveDeploymentEnv(environment);

	return {
		dsn,
		environment: resolvedEnv,
		release: release ?? process.env.GIT_SHA ?? process.env.npm_package_version,
		sendDefaultPii: false,
		attachStacktrace: true,
		// Full sampling in development; reduced in staging/production to limit overhead.
		tracesSampleRate: resolvedEnv === "development" ? 1.0 : 0.1,

		initialScope: {
			tags: {
				surface,
				...(tier ? { tier } : {}),
			},
			...(workspaceHash ? { user: { id: workspaceHash } } : {}),
		},

		// Drop auto-capture integrations that can produce breadcrumbs with sensitive data
		integrations(defaultIntegrations: AnyIntegration[]) {
			return defaultIntegrations.filter((i) => !["Breadcrumbs", "Console", "Http"].includes(i.name));
		},

		beforeSend(event) {
			// Strip extra keys outside allowlist
			if (event.extra) {
				const filtered: Record<string, unknown> = {};
				for (const key of EXTRA_ALLOWLIST) {
					if (key in event.extra) {
						filtered[key] = event.extra[key];
					}
				}
				event.extra = filtered;
			}

			// Clear runtime args (may contain file paths)
			if (event.contexts?.runtime) {
				(event.contexts.runtime as Record<string, unknown>).args = undefined;
			}

			// Clear request body (may contain RPC payloads)
			if (event.request) {
				event.request.data = undefined;
			}

			// Clear all breadcrumb data payloads
			if (event.breadcrumbs?.values) {
				const breadcrumbs = event.breadcrumbs.values();
				for (const crumb of breadcrumbs) {
					crumb.data = undefined;
				}
			}

			// Scrub strings in exception messages and stack frame filenames
			if (event.exception?.values) {
				for (const exc of event.exception.values) {
					if (exc.value) {
						exc.value = scrubString(exc.value);
					}
					if (exc.stacktrace?.frames) {
						for (const frame of exc.stacktrace.frames) {
							if (frame.filename) {
								frame.filename = scrubString(frame.filename);
							}
							if (frame.abs_path) {
								frame.abs_path = scrubString(frame.abs_path);
							}
						}
					}
				}
			}

			// Scrub event message
			if (event.message) {
				event.message = scrubString(event.message);
			}

			return event;
		},

		beforeBreadcrumb(breadcrumb) {
			const cat = breadcrumb.category ?? "";
			if (BLOCKED_BREADCRUMB_CATEGORIES.has(cat)) {
				// Explicit opt-in via _allow sentinel bypasses the filter
				const data = breadcrumb.data as Record<string, unknown> | undefined;
				if (data?._allow === true) {
					const { _allow: _, ...rest } = data;
					breadcrumb.data = rest as Record<string, unknown>;
					return breadcrumb;
				}
				return null;
			}
			return breadcrumb;
		},
	};
}
